package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.comparisonai.*;import com.aistock.prediction.comparison.*;import com.aistock.prediction.explanation.MaasClient;import com.aistock.common.BusinessException;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.test.context.web.WebAppConfiguration;import org.springframework.mock.web.MockCookie;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") @WebAppConfiguration @SpringJUnitConfig(ComparisonAiHttpTest.Config.class)
class ComparisonAiHttpTest {
 static class Fake implements MaasClient {int calls;boolean fail;String model="fixture";public boolean enabled(){return true;}public String model(){return model;}public JsonNode generate(Map<String,String> f){throw new UnsupportedOperationException();}public JsonNode generateComparison(Map<String,String> f){calls++;if(fail)throw new BusinessException("AI_UNAVAILABLE","fixture",org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE);var m=ComparisonAiSamples.M;var root=m.createObjectNode();var ps=root.putArray("paragraphs");for(String kind:List.of("overview","readout","risk")){var keys=ComparisonAiTemplate.required(kind,f);var p=ps.addObject().put("kind",kind).put("template",keys.stream().map(k->"{{"+k+"}}").collect(java.util.stream.Collectors.joining("。")));p.set("refs",m.valueToTree(keys));}return root;}}
 @Configuration @Import({ModelHttpTest.Config.class,ComparisonAiController.class}) static class Config {
  @Bean Fake fake(){return new Fake();}
  @Bean ComparisonAiService service(ModelDatabaseFixture db,ObjectMapper mapper,Fake fake){var clock=Clock.fixed(Instant.parse("2026-10-13T00:00:00Z"),ZoneOffset.UTC);return new ComparisonAiService(new ComparisonAiRepository(db.jdbc,mapper,clock),new ComparisonRepository(db.jdbc,mapper),fake,mapper,clock,true);}
 }
 @Autowired WebApplicationContext context;@Autowired Fake fake;@Autowired ObjectMapper mapper;
 @Test void authenticatedCreationReplayCacheFailureAndReadOnlyRecovery()throws Exception {
  var db=new ModelDatabaseFixture();var userId=UUID.nameUUIDFromBytes("user-session".getBytes());new ComparisonAiMysqlTest().seed(db,userId,ComparisonAiSamples.saved());fake.calls=0;fake.fail=false;fake.model="fixture";
  var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var user=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");String uri="/api/v1/comparison-explanations";var in=new ComparisonAiInput(UUID.randomUUID(),ComparisonAiSamples.ID);String body=mapper.writeValueAsString(in);
  mvc.perform(get(uri).param("comparisonId",in.comparisonId().toString())).andExpect(status().isUnauthorized());
  mvc.perform(post(uri).cookie(user).contentType("application/json").content(body)).andExpect(status().isForbidden());
  mvc.perform(post(uri).cookie(user,csrf).header("Origin","https://invalid.example").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isForbidden());
  for(String bad:List.of(body+" {}",body.substring(0,body.length()-1)+",\"owner\":\"forged\"}",body.substring(0,body.length()-1)+",\"operationId\":\""+in.operationId()+"\"}"))mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(bad)).andExpect(status().isUnprocessableEntity());
  mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content("x".repeat(513))).andExpect(status().isPayloadTooLarge());assertEquals(0,fake.calls);
  var first=mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.data.state").value("SUCCEEDED")).andReturn();String explanation=mapper.readTree(first.getResponse().getContentAsString()).path("data").path("explanationId").asText();
  mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk());
  mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(mapper.writeValueAsString(new ComparisonAiInput(UUID.randomUUID(),in.comparisonId())))).andExpect(status().isOk());assertEquals(1,fake.calls);
  mvc.perform(get(uri+"/"+explanation).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());mvc.perform(get(uri+"/operations/"+in.operationId()).cookie(user)).andExpect(status().isOk());mvc.perform(get(uri).cookie(user).param("comparisonId",in.comparisonId().toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.latest.explanationId").value(explanation));assertEquals(1,fake.calls);
  fake.fail=true;fake.model="new-model";var failed=new ComparisonAiInput(UUID.randomUUID(),in.comparisonId());mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(mapper.writeValueAsString(failed))).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("FAILED"));mvc.perform(get(uri).cookie(user).param("comparisonId",in.comparisonId().toString())).andExpect(jsonPath("$.data.latest.explanationId").value(explanation));assertEquals(2,fake.calls);
 }
}
